INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (58,1,'<p> Для восстановления пароля укажите электронный адрес, указанный Вами\nпри регистрации.</p> <p>На него будет выслан автоматически созданный\nпароль.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (59,1,'<h1>Добро пожаловать!</h1>\n<p>Это демонстрационный сайт Energine Simple — системы управления для сайтов-визиток: страницы, новости, галерея, обратная связь и кабинет посетителя.</p>\n<ul>\n<li>Несколько языков: переводятся и страницы, и подписи интерфейса.</li>\n<li>Права: у каждой группы пользователей свои права на каждый раздел.</li>\n<li>Тексты правятся прямо на странице, в визуальном редакторе.</li>\n<li>Файлы хранятся в репозитории сайта и используются в текстах, новостях и галерее.</li>\n<li>Структура сайта — дерево разделов, которое меняется в админке.</li>\n</ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (59,2,'<h1>Вітаємо!</h1>\n<p>Це демонстраційний сайт Energine Simple — системи керування для сайтів-візиток: сторінки, новини, галерея, зворотний зв’язок і кабінет відвідувача.</p>\n<ul>\n<li>Кілька мов: перекладаються і сторінки, і підписи інтерфейсу.</li>\n<li>Права: у кожної групи користувачів свої права на кожен розділ.</li>\n<li>Тексти редагуються просто на сторінці, у візуальному редакторі.</li>\n<li>Файли зберігаються в репозиторії сайту й використовуються в текстах, новинах і галереї.</li>\n<li>Структура сайту — дерево розділів, яке змінюється в адмінці.</li>\n</ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (60,1,'\n                    <p><b>Вводная:</b></p><p>Начиная с версии energine 2.11.0 структура проекта изменилась.&nbsp;Теперь релизы ядра energine могут храниться в отдельной директории (например /var/www/energine).&nbsp;А сами проекты теперь больше не тянут ядро и модули через svn:externals, а подключают нужные версии модулей&nbsp;ядра и сторонние модули через указанные местоположения в конфиге.</p><p>Итак, для того, чтобы развернуть проект на базе energine у себя, необходимо:</p><p>1. Создать директорию для хранения ядер (например <b>/var/www/energine</b>)</p><p><b><i>mkdir /var/www/energine</i></b></p><p>2. Отчекаутить из svn одно из стабильных ядер (начиная с версии <b>tags/2.11.2.beta</b>) или загрузить подготовленный zip-архив с релизом ядра.</p><p>Пример чекаута двух стабильных релизов и trunk:</p><p><b><i>cd /var/www/energine</i></b></p><p><b><i>svn checkout https://energine.googlecode.com/svn/tags/2.11.1 2.11.1</i></b></p><p><b><i>svn checkout https://energine.googlecode.com/svn/tags/2.11.2.beta 2.11.2.beta</i></b></p><p><b><i>svn checkout https://energine.googlecode.com/svn/trunk trunk</i></b></p><p>3. Отчекаутить из svn проект starter из одного из стабильных релизов проекта, либо bleeding-edge релиз из trunk:</p><p>Пример:</p><p><b><i>cd /home/username/projects</i></b></p><p><b><i>svn checkout https://energine.googlecode.com/svn/tags/2.11.2.beta/starter www.mynewsite.com</i></b></p><p>4. Далее необходимо создать базу данных mysql</p><p>4.1. импортировать базовую структуру из <b>sql/starter.structure.sql</b></p><p>4.2. импортировать хранимые процедуры из <b>sql/starter.routines.sql</b> (важно: необходимо поправить DEFINER в коде. Если у пользователя mysql нет прав на создание хранимых процедур - этот шаг можно пропустить, но в системе будет доступно только локальное хранилище.</p><p>4.3. импортировать системные данные из<b> sql/starter.data.sql</b></p><p>5. Скопировать конфигурационный файл из <b>configs/system.config.default.php</b> в <b>configs/system.config.username.php</b>,&nbsp;а затем сделать симлинк (или скопировать) из <b>configs/system.config.username.php</b> в <b>htdocs/system.config.php</b></p><p>6. Отредактировать конфиг, по крайней мере ввести туда такие данные:</p><p>- указать директорию с текущим ядром, откуда будут тянуться <b>setup</b> и <b>core/modules</b>,</p><p>- корректные настройки базы данных,</p><p>- домен сайта,</p><p>- перечень модулей, которые будут доступны на сайте, с указанием полного пути к месторасположению каждого модуля,</p><p>- поправить адреса электронной почты.</p><p>7. Настроить nginx или apache.</p><p>Пример конфига nginx находится в jambalaya/.nginx.conf.example</p><p>Пример конфига Apache находится в jambalaya/.htaccess (подразумевается, что VirtualHost у Вас уже настроен)</p><p>8. Выставить права на запись на директорию <b>htdocs</b>, <b>htdocs/uploads</b> и запустить <b>http://&lt;адрес проекта&gt;/setup/</b></p><p>Если все пойдет как нужно - у Вас будет минимально-рабочая копия системы на базе движка Energine.</p><p>9. Разработать сайт на базе Energine ;)</p>\n                  ');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (61,1,'<p>Сайт состоит из разделов; у каждого раздела есть шаблон разметки и набор компонентов. Тексты правятся прямо на странице: администратор включает режим редактирования и меняет содержимое без отдельной формы.</p>\n  \n  <h3>Посмотреть</h3><ul><li><a href=\"/\">Главная страница</a> — текстовые блоки</li><li><a href=\"/sitemap/\">Карта сайта</a> — всё дерево разделов</li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/structure/\">Управление структурой</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (61,2,'<p>Сайт складається з розділів; у кожного є шаблон розмітки та набір компонентів. Тексти правляться просто на сторінці: адміністратор вмикає режим редагування та змінює вміст без окремої форми.</p>\n  \n  <h3>Подивитися</h3><ul><li><a href=\"/ua/\">Головна сторінка</a></li><li><a href=\"/ua/sitemap/\">Карта сайту</a></li></ul>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/structure/\">Керування структурою</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (62,1,'<p>Лента с постраничной навигацией, страница новости, вложения, архив по датам. Новости с будущей датой и снятые с публикации видны только редактору.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/news/\">Лента новостей</a></li><li><a href=\"/news/2013/4/\">Архив за апрель 2013</a></li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/news-editor/\">Редактор новостей</a></li><li><a href=\"/admin/news-categories/\">Рубрики новостей</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (62,2,'<p>Стрічка з посторінковою навігацією, сторінка новини, вкладення, архів за датами. Новини з майбутньою датою та зняті з публікації бачить лише редактор.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/news/\">Стрічка новин</a></li><li><a href=\"/ua/news/2013/4/\">Архів за квітень 2013</a></li></ul>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/news-editor/\">Редактор новин</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (69,1,'<p>Файловый менеджер с деревом папок, загрузкой и миниатюрами. Изображения отдаются через ресайзер: один исходник и любые размеры в разметке. К странице или новости можно прикрепить набор файлов — он выводится лентой.</p>\n  \n  <h3>Посмотреть</h3><ul><li><a href=\"/media/\">Галерея</a> — вложения раздела</li><li><a href=\"/news/1--dobro-pozhalovaty/\">Новость с вложением</a></li></ul>\n  <h3>В админке</h3><p>Файловый менеджер открывается из режима редактирования и из форм, где есть поле файла.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (69,2,'<p>Файловий менеджер із деревом тек, завантаженням і мініатюрами. Зображення віддаються через ресайзер: одне джерело і будь-які розміри в розмітці.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/media/\">Галерея</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (70,1,'<p>Пользователи объединяются в группы, у группы свои права на каждый раздел: без доступа, чтение, изменение, полный доступ. Есть регистрация, восстановление пароля и профиль.</p>\n  <p>Демо-пользователь: <b>olena@example.com</b> / <b>demo</b>.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/register/\">Регистрация</a></li><li><a href=\"/profile/\">Профиль</a> — после входа</li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/users/\">Пользователи</a></li><li><a href=\"/admin/users/roles/\">Роли и права</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (70,2,'<p>Користувачі об’єднуються в групи, у групи свої права на кожен розділ: без доступу, читання, зміна, повний доступ. Є реєстрація, відновлення пароля та профіль.</p>\n  <p>Демо-користувач: <b>olena@example.com</b> / <b>demo</b>.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/register/\">Реєстрація</a></li></ul>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/users/\">Користувачі</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (71,1,'<p>Сайт двуязычный: русский и украинский. Переводится и содержимое, и подписи интерфейса. Язык по умолчанию идёт без префикса в адресе, остальные — с префиксом.</p>\n  <p>Честная оговорка: сообщения обратной связи хранятся одной версией на оба языка — в движке у этой таблицы нет переводов.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/ua/news/\">Новости по-украински</a></li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/translations/\">Переводы интерфейса</a></li><li><a href=\"/admin/translations/languages/\">Языки</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (71,2,'<p>Сайт двомовний: російська та українська. Перекладається і вміст, і підписи інтерфейсу. Мова за замовчуванням іде без префікса в адресі.</p>\n  <p>Чесне застереження: повідомлення зворотного зв’язку зберігаються однією версією на обидві мови — у рушія в цієї таблиці немає перекладів.</p>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/translations/\">Переклади інтерфейсу</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (72,1,'<p>Человекопонятные адреса, отдельные заголовок, ключевые слова и описание для каждой страницы и языка, настройка индексации, карта сайта для поисковиков и robots.</p>\n  <p>Особенность хоста: файл robots.txt отдаёт веб-сервер, поэтому компонент доступен по адресу со слешем.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/google-sitemap/\">Карта сайта для поисковиков</a></li><li><a href=\"/robots.txt/\">robots от движка</a></li><li><a href=\"/sitemap/\">Карта сайта для людей</a></li></ul>\n  <h3>В админке</h3><p>Метаданные страницы правятся в свойствах раздела в <a href=\"/admin/structure/\">редакторе структуры</a>.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (72,2,'<p>Зрозумілі адреси, окремі заголовок, ключові слова й опис для кожної сторінки та мови, налаштування індексації, карта сайту для пошуковиків і robots.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/sitemap/\">Карта сайту</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (73,1,'<p>Разделы админки собраны на <a href=\"/admin/\">одной странице</a>; вход — по ссылке «Вход» вверху страницы.</p>\n<p>Кроме редакторов содержимого есть журнал действий и настройки сайта: название, описание и параметры для поисковых систем.</p>\n<h3>В админке</h3><ul><li><a href=\"/admin/action-log/\">Журнал действий</a></li><li><a href=\"/admin/settings/\">Настройки сайта</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (73,2,'<p>Розділи адмінки зібрані на <a href=\"/ua/admin/\">одній сторінці</a>; вхід — за посиланням «Вхід» угорі сторінки.</p>\n<h3>В адмінці</h3><ul><li><a href=\"/ua/admin/action-log/\">Журнал дій</a></li><li><a href=\"/ua/admin/settings/\">Налаштування сайту</a></li></ul>');
